import { MonoTypeOperatorFunction, Observable, SchedulerLike, asyncScheduler, debounceTime, tap } from 'rxjs';

// Modified from this answer: https://stackoverflow.com/a/74804586/1098252
export const debounceTimeAfter = <T>(
	opts: {
		numberToSkip: number,
		duration: number,
		trailing?: boolean
	},
	scheduler: SchedulerLike = asyncScheduler
): MonoTypeOperatorFunction<T> => {
	return (source$: Observable<T>): Observable<T> => {
		return new Observable<T>(subscriber => {
			// keep track of iteration count until flow completes
			let iterationCount = 0;

			return source$
				.pipe(
					tap(value => {
						// increment iteration count
						iterationCount++;
						// emit value to subscriber when it is <= iteration amount
						if (iterationCount <= opts.numberToSkip) {
							subscriber.next(value);
						}
					}),
					// debounce according to provided duration
					debounceTime(opts.duration, scheduler),
					tap(value => {
						// emit subsequent values to subscriber
						if (opts.trailing && iterationCount > opts.numberToSkip) {
							subscriber.next(value);
						}

						// reset iteration count when debounce is completed
						iterationCount = 0;
					}),
				)
				.subscribe();
		});
	};
};

export const debounceTimeAfterFirst = <T>(
	duration: number,
	trailing?: boolean,
	scheduler: SchedulerLike = asyncScheduler,
): MonoTypeOperatorFunction<T> => {
	return debounceTimeAfter({ numberToSkip: 1, duration, trailing }, scheduler);
}