export class HSL {

	public static fromHex(hex: string): HSL {
		const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex)!;

		let r = parseInt(result[1], 16);
		let g = parseInt(result[2], 16);
		let b = parseInt(result[3], 16);

		r /= 255;
		g /= 255;
		b /= 255;

		const max = Math.max(r, g, b), min = Math.min(r, g, b);
		let h: number, s, l = (max + min) / 2;

		if (max === min) {
			h = s = 0; // achromatic
		} else {
			const d = max - min;
			s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
			switch (max) {
				case r: h = (g - b) / d + (g < b ? 6 : 0); break;
				case g: h = (b - r) / d + 2; break;
				case b: h = (r - g) / d + 4; break;
			}
			h = h! / 6
		}

		s = s * 100;
		l = l * 100;
		h = h * 360;

		return new HSL(h, s, l);
	}

	constructor(public h: number, public s: number, public l: number) {
		this.h = Math.min(Math.max(0, h), 360);
		this.s = Math.min(Math.max(0, s), 100);
		this.l = Math.min(Math.max(0, l), 100);
	}

	public darken(percent: number): HSL {
		return new HSL(this.h, this.s, this.l - percent);
	}

	public lighten(percent: number): HSL {
		return new HSL(this.h, this.s, this.l + percent);
	}

	public toHex(): string {
		const rgb = this.toRGB();

		let R = Math.round(rgb[0]).toString(16);
		let G = Math.round(rgb[1]).toString(16);
		let B = Math.round(rgb[2]).toString(16);

		if (R.length === 1) {
			R = '0' + R;
		}
		if (G.length === 1) {
			G = '0' + G;
		}
		if (B.length === 1) {
			B = '0' + B;
		}

		return '#' + R + G + B;
	}

	public toRGBA(alpha: number): string {
		alpha = Math.min(Math.max(0, alpha), 1);
		const rgb = this.toRGB();
		return `rgba(${rgb[0].toFixed(2)}, ${rgb[1].toFixed(2)}, ${rgb[2].toFixed(2)}, ${alpha.toFixed(2)})`;
	}

	private toRGB(): number[] {
		const s = this.s / 100.0;
		const l = this.l / 100.0;

		const c = (1.0 - Math.abs(2.0 * l - 1.0)) * s;
		const x = c * (1.0 - Math.abs((this.h / 60.0) % 2.0 - 1.0));
		const m = l - c / 2.0;
		let r = 0;
		let g = 0;
		let b = 0;

		if (0 <= this.h && this.h < 60) {
			r = c; g = x; b = 0;
		} else if (60 <= this.h && this.h < 120) {
			r = x; g = c; b = 0;
		} else if (120 <= this.h && this.h < 180) {
			r = 0; g = c; b = x;
		} else if (180 <= this.h && this.h < 240) {
			r = 0; g = x; b = c;
		} else if (240 <= this.h && this.h < 300) {
			r = x; g = 0; b = c;
		} else if (300 <= this.h && this.h < 360) {
			r = c; g = 0; b = x;
		}

		return [
			Math.min(Math.max((r + m) * 255, 0), 255),
			Math.min(Math.max((g + m) * 255, 0), 255),
			Math.min(Math.max((b + m) * 255, 0), 255)
		];
	}
}