import { ActivatedRouteSnapshot, Data, Event, NavigationEnd, Router } from '@angular/router';
import { filter, map, Observable } from 'rxjs';

export function extractRouteData(router: Router): ((source: Observable<Event>) => Observable<Data>) {
	return (source: Observable<Event>) => {
		return source.pipe(
			filter(event => event instanceof NavigationEnd),
			map(() => {
				let route: ActivatedRouteSnapshot = router.routerState.snapshot.root;
				while (route.firstChild) {
					route = route.firstChild;
				}
				return route;
			}),
			filter((route) => route.outlet === 'primary'),
			map(route => route.data || {}));
	};
}