export type ValueExtractor = string | ((obj: any) => any);

export class ObjectUtils {
	public static extractValue(obj: object | unknown[] | undefined | null, extractor: ValueExtractor): unknown {
		if (obj) {
			if (typeof extractor === 'string') {
				return extractor
					.replace(/\[|\]\.?/g, '.') // replace any array indexing (e.g. [1]) with dots, so array[1].field becomes array.1..field
					.split('.') // split the string into array
					.filter(s => !!s) // filter out any empty items, likely from the result of double dots in the array conversion above
					.reduce((acc, val) => acc && (acc as any)[val], obj); // iterate over the chain of fields applying each field to the result of the previous
			} else {
				return extractor(obj);
			}
		} else {
			return undefined;
		}
	}
}