export class ArrayUtils {

	/**
	 *
	 * @param direction
	 * @param startIndex
	 * @param arrayLength
	 * @param numColumns
	 * @returns a new index, starting from 'startIndex' and moving one step in 'direction', wrapping as necessary at the edges of the virtual grid
	 */
	public static navigate1DArrayIndexIn2DSpace(direction: 'up' | 'down' | 'left' | 'right', startIndex: number, arrayLength: number, numColumns: number): number {
		if (direction === 'up') {
			if (startIndex >= numColumns) {
				startIndex -= numColumns;
			} else {
				const numFullRows = Math.floor(arrayLength / numColumns);
				startIndex = numFullRows * numColumns + startIndex;
				if (startIndex >= arrayLength) {
					startIndex -= numColumns; // we hit empty space in a partial row, move up to the last full row
				}
			}
		} else if (direction === 'down') {
			startIndex += numColumns;
			if (startIndex >= arrayLength) {
				startIndex %= numColumns
			}
		} else if (direction === 'left') {
			startIndex--;
			if (startIndex < 0) {
				startIndex += arrayLength;
			}
		} else if (direction === 'right') {
			startIndex++;
			if (startIndex >= arrayLength) {
				startIndex = 0;
			}
		}

		return startIndex;
	}
}